t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back down the beach, past the pirate camp: the crate of boots and the fragile crate with the lens sit at its south end."] = "Redescendez la plage après le camp pirate : la caisse de bottes et la caisse fragile avec la lentille se trouvent à son extrémité sud.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "Retour au camp Tranchecrin. Les Géomanciennes et les Défenseurs tiennent sa moitié est ; {npc:3438} se promène parmi eux.",
		["Back west along the road."] = "Revenez vers l'ouest par la route.",
		["East to the {area:1703}; {npc:9316} stands at the camp just south of it."] = "À l'est vers {area:1703} ; {npc:9316} se tient au camp juste au sud.",
		["East to {area:392}, on the coast."] = "À l'est vers {area:392}, sur la côte.",
		["Follow the road east to the outpost above the {area:814}."] = "Suivez la route vers l'est jusqu'à l'avant-poste au-dessus de {area:814}.",
		["Follow the road south-east to {area:392} on the coast."] = "Suivez la route vers le sud-est jusqu'à {area:392}, sur la côte.",
		["Oasis Snapjaws crawl around {area:387}, south-west of the {area:380}, and around the {area:388}."] = "Les Gueules d'acier des oasis rampent autour de {area:387}, au sud-ouest de la {area:380}, et autour de {area:388}.",
		["Razormane camp"] = "Camp Tranchecrin",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "Au sud vers le poste de guet de {npc:3389}, à la frontière kolkar.",
		["South-east of the {area:380}. Test the seeds at the bubbling fissure on the oasis' east bank."] = "Au sud-est de la {area:380}. Testez les graines à la fissure bouillonnante sur la rive est de l'oasis.",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "Les Rôdeurs des savanes chassent dans les plaines entre la ville et le camp Tranchecrin à l'est. Dans le camp, les Sourciers et les Tisseuses d’épines tiennent la moitié ouest, les Chasseurs le centre ; les caisses de ravitaillement se trouvent à l'extrémité est.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "Les bassins se trouvent juste au nord de {npc:3389}. Entrez dans l'eau pour les explorer ; les Champignons chargés pour Helbrim poussent autour. Tuez chaque kolkar sur votre passage pour les brassards.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}, east of {npc:9316}."] = "Les seaux à outils avec les rondelles se trouvent autour du site de forage de la KapitalRisk, dans {area:382}, à l'est de {npc:9316}.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "Les Lézards-tonnerre et les Foudroyants paissent juste de l'autre côté du pont, sous {area:379}.",
		["Thunder lizards across the river"] = "Lézards-tonnerre de l'autre côté de la rivière",
		["Zhevra"] = "Zhévras",
		["Zhevra Runners graze north and east of town."] = "Les Messagers zhévra paissent au nord et à l'est de la ville.",
		["{area:1898} cultists"] = "Sectateurs de {area:1898}",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380} est votre base pour ce guide. Tous ceux dont vous avez besoin se tiennent à quelques pas de l'auberge.",
		["{npc:3442} in {area:392}: later, on the way"] = "{npc:3442} à {area:392} : plus tard, en chemin",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442} : la console est dans {area:382}, plus tard",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449} : les harpies viendront plus tard, dans {area:383}",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878} campe au bord de la route de la {area:380} à {area:392}. Le {object:58369} se trouve dans le sud du camp Tranchecrin, juste au nord de lui.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} fabrique le {item:6636} avec le goudron et la bourse. Utilisez-le près du brasero à côté de lui pour révéler la {npc:5893}, tuez-la pour obtenir la {item:6655}, puis placez la braise dans le brasero.",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900} attend sur la berge au sud de {area:379}, de l'autre côté du pont.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} se tient sur la crête au nord du camp Tranchecrin.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {npc:2523}, votre {item:5176} et le {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, sur le quai",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301} : {area:228} en {zone:1421}, guide suivant",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["At the {area:2362}"] = "À {area:2362}",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "Volez jusqu'à {area:1638} : {npc:3033} vous entraîne sur {area:1639}. Éolides : revolez ensuite à {zone:1454} pour le zeppelin.",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "Longez la rive du lac vers le sud-est et nagez jusqu'à l'{area:172}. Les gnolls Poil-Putride couvrent l'île ; chaque type lâche de l'ichor. N'entrez pas dans le {area:235} au nord, sauf pour la niche facultative : les gnolls y sont de niveau 18-22.",
		["Follow the lake shore south-east toward {area:172}: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Suivez la rive du lac vers le sud-est en direction de {area:172} : les Déchiqueteurs Aileron noir et les Chasse-marée Aileron noir qui la longent lâchent les yeux de murloc.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Suivez la route vers le nord-est jusqu'à la maison des Yorick, à {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Suivez la route vers le sud. {object:1627} se trouve au bord, au nord de Bois-du-Bûcher.",
		["Keep it: Thork at the {area:380}"] = "Gardez-la : Thork à {area:380}",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "Gardez-la : {npc:2216} à {area:272}, dans un guide ultérieur",
		["Mottled Worgs"] = "Worgs chamarrés",
		["Mottled Worgs prowl the hills around the house."] = "Les Worgs chamarrés rôdent sur les collines autour de la maison.",
		["North again to the Yoricks' house."] = "Retournez au nord jusqu'à la maison des Yorick.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Au nord de {area:228}. {npc:1983} hante le {area:240} : tuez-le, puis traversez le champ.",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "Descendez la route vers le sud-est jusqu'à {area:233}. Les Protecteurs de Dalaran gardent les abords et les Mages de Dalaran la ville ; les deux lâchent des pendentifs. Des Sorciers et des Gardiens de Dalaran patrouillent sur les routes alentour. Évitez le centre, où se tient {npc:2120}.",
		["Speak with {npc:10540}, in Grommash Hold"] = "Parlez à {npc:10540}, dans le fort Grommash",
		["Speak with {npc:3230}, in Grommash Hold"] = "Parlez à {npc:3230}, dans le fort Grommash",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "Les Rôdeurs lacustres et les Oracles Aileron noir se trouvent sur la rive du lac au sud de {area:237}, à l'est de {area:228}.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Les massettes et les herbes-lances poussent au bord de l'eau dans {object:172958}, à l'est de la Herse.",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "{object:1593} se trouve à l'embarcadère du bac, sur la rive du lac à l'est de {area:228}.",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "{object:177790} se trouve sur la côte à l'ouest du {area:240}. Il contient {item:15882} pour {quest:30}.",
		["Vile Fin murlocs"] = "Murlocs Aileron noir",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:1338} shore"] = "Rive de {area:1338}",
		["{area:233} comes later, on the southern loop"] = "{area:233} viendra plus tard, sur la boucle sud",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, dans un {object:177785} au fond du lac",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317} : butin rare des gnolls",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{npc:11798}, à {area:2361}, y emmène les druides ; volez ensuite jusqu'à {zone:1454} pour le zeppelin",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, à {area:2362}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937} : pour Quinn, sur la route du nord à la fin",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} attend au nord-est de la maison. Escortez-le jusqu'à {npc:1950} ; des worgs attaquent en chemin.",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121} : {quest:516}, sur la boucle sud",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entraîne les paladins à {area:159}, à courte distance au nord par la route depuis les tours des zeppelins. Redescendez la même route pour la forêt des Pins argentés.",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} et {npc:3347} tiennent la boutique d'alchimie de la Herse ; {npc:11046} est juste à côté.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, dans le fort Grommash",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949} : {quest:93739}, une tournée des chefs de la Horde",
		["{object:1599}, just east of the keep"] = "{object:1599}, juste à l'est du donjon",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127} : {area:384}, guide suivant",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Aidez {npc:261366} : restez près de lui quand {npc:261367} et les soldats de marine de {area:21} montent la crête",
		["Bael'dun fortress"] = "Forteresse de Bael'dun",
		["Bristleback camps"] = "Camps Dos-hirsute",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran est enchaîné dans le camp huran à l'ouest de la route.",
		["Down the {area:458} to {area:378} again."] = "Redescendez la {area:458} jusqu'au {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Remplissez l'{item:7766} au point d'eau des huran",
		["Fly to {area:1637} to train your level 20 ranks. {npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "Volez jusqu'à {area:1637} pour apprendre vos rangs de niveau 20. {npc:3354} est dans la {object:172958}, {npc:5892} dans la {object:172957}.",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "Volez jusqu'aux {area:1638} et apprenez vos rangs de niveau 20 : {npc:3033} est sur la {area:1639}.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Volez jusqu'aux {area:1638} pour vous entraîner : {npc:3033} est sur la {area:1639}.",
		["Fly to {area:392}"] = "Voler jusqu'à {area:392}",
		["Follow the {area:458} south to {area:378}."] = "Suivez la {area:458} vers le sud jusqu'au {area:378}.",
		["He gives you the {item:15826}"] = "Il vous donne le {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Il propose ensuite {quest:1838} (1838, niveau 30) : elle demande {area:1717} et vous envoie partout en Kalimdor et dans les Royaumes de l'Est. Le guide de classe Guerrier {quest:1838} la couvre.",
		["Keep it: the {object:107045} is beside {area:272}"] = "Gardez-la : le {object:107045} est à côté d'{area:272}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Gardez-la : {npc:12696} en {zone:1440}, guide suivant",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "Gardez-la : {npc:5875} à {zone:1454}, à la fin de ce guide",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Au nord vers les {area:383}. {npc:3682} campe au pied des collines ; {npc:261366}, l'ermite sur la crête derrière lui, n'a du travail pour vous qu'une fois que {npc:3682} vous y envoie.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "En redescendant la {area:458} vers le {area:378} : les Pillards tranchecrin parmi les camps Dos-hirsute, de part et d'autre de la route au nord du camp, portent {item:277277}. Rendez-les à {npc:3432} lors de votre dernier arrêt à {area:380}.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Taurens : le {npc:11957} attend sur la colline sud au-dessus du pont. Éolides : l'{npc:272054} se tient au sud des ponts jumeaux. Ensuite, les tanières à l'est du lac : quittez votre forme, cliquez sur la statue à l'entrée pour cinq minutes de camouflage, évitez les esprits à l'intérieur et prenez une relique de chaque ; la {item:280680} se trouve au pied de la statue de chat blanc.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. Every Bristleback drops a tusk; {npc:3432}'s wife lies at the north edge. Keep one {item:5075}. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "Les camps des huran Dos-hirsute s'étendent sur les plaines au nord du {area:378}, de part et d'autre de la {area:458}. Chaque Dos-hirsute laisse une défense ; la femme de {npc:3432} gît au bord nord. Gardez un {item:5075}. {quest:883}, un kodo gris, erre parfois ici : son sabot lance une quête.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Les Surveillants de la KapitalRisk et Massacreurs de la KapitalRisk de la mine au nord-est de la zone laissent l'{item:5097}.",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "La machine volante des nains repose sur sa plateforme dans le site de fouilles.",
		["The flying machine"] = "La machine volante",
		["The {area:2363}"] = "Les {area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} est le canyon sous {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} se trouve au bord nord de {area:382}, près de la tour de la KapitalRisk. Il contient le {item:15883} pour {quest:30}.",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Les Faucons-tonnerre des nuages tournoient au-dessus des mêmes plaines au sud du camp.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Les Têtes-tonnerre paissent dans les plaines juste au sud du {area:378}. {quest:884}, un lézard-tonnerre bleu, erre parmi eux : sa pointe caudale lance une quête.",
		["Twitching Antennae"] = "Antennes frémissantes",
		["Twitching Antennae from the silithid"] = "Antennes frémissantes des silithides",
		["Venture Co. tower"] = "Tour de la KapitalRisk",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852} : Kodos égarés des Tarides ({npc:3234}) dans les plaines autour du camp kolkar",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885} : utilisez une moitié au {area:2362}",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} auprès de {npc:3490} ; les herboristes en cueillent dans les plaines",
		["{item:2449}: herbalists pick it here"] = "{item:2449} : les herboristes en cueillent ici",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} à {area:2361} y emmène les druides",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802} : l'accueil de {npc:3033}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296} : utilisez le {item:15826} sur elles ; elles errent dans les plaines tout autour de {area:380}",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, dans l'arbre juste à l'est de {npc:3341}",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341} attend dans un petit camp plus au sud, sur la route de {area:359}.",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389} se tient au poste de guet kolkar juste à l'ouest de {area:380}.",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394} se tient dans le camp kolkar au nord-ouest de {npc:3389}.",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395} se promène parmi les kolkars à l'{area:388}, au sud-est de {area:380}.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396} mène les kolkars sur la rive ouest de l'{area:387}, au sud de {npc:3389}. Rendez sa tête à {npc:3389} lors de votre dernier arrêt à {area:380}.",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428} : les œufs sont au {area:390}, plus tard",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en haut de la tour",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}. Gardez-la : Kadrak au {area:1703}, guide suivant",
		["{npc:3430}, in the cage"] = "{npc:3430}, dans la cage",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} propose {quest:95774} une fois {quest:4921} rendue",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, au bord nord du camp",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}, à côté du maître des coursiers du vent. Gardez-la : {quest:1483} se fait aux Serres-Rocheuses, plus tard",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} est enchaîné dans le fort. Parlez-lui pour lancer l'escorte et restez près de lui : des soldats de Theramore attaquent à la sortie. Il vous ramène à {area:392}.",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878} campe au bord de la route à l'est de {area:380}.",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}, juste à l'ouest de {npc:3341}",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} attend sur la colline au sud de {area:392}, sur votre route vers le nord.",
		["{npc:5909}, a few steps away"] = "{npc:5909}, à quelques pas",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} se tient dans la {object:172961}, à l'ouest de la ville.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018} : {npc:4606} à {zone:1458}, dans deux guides",
		["{object:3972} poster"] = "Affiche {object:3972}",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458} : {npc:7233}, près de la {area:382}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "De nouveau sur la route vers le sud. Là où elle tourne vers l'est dans {area:287}, {npc:2214} attend à {area:285}.",
		["Back to {npc:8582}"] = "Retour à {npc:8582}",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Chaque naga Irequeue de la grève au nord de l'avant-poste lâche des têtes.",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Suivez la route vers le nord en direction du {area:467}. Des Coursiers à ramure ({npc:4018}) paissent en chemin ; Bêtes de sève ({npc:4020}), Coureurs crépusculaires ({npc:4067}) et Dragons-faë ({npc:4016}) parcourent les bois sous le pic, et les druides cénariens tiennent le bosquet là-bas.",
		["Follow the road west to {area:460}."] = "Suivez la route vers l'ouest jusqu'à {area:460}.",
		["Gaea Dirt Mounds"] = "Monticules de poussière de Gaea ({object:177929})",
		["Gaea Seeds"] = "Graines de Gaea ({item:16205})",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "Continuez vers le nord sur la route. {npc:12862} attend au camp de bûcherons Warsong, au sud de Bois-brisé.",
		["Naga heads"] = "Têtes de nagas",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Au sud-ouest de Roche-Soleil s'étend le {area:465}. Plantez les Graines de Gaea dans les monticules de terre au fond de la vallée ; les élémentaires de feu lâchent {item:16312}. Harpies et Embusquées Rougefurie nichent au nord, Tueuses et Volplumes au sud.",
		["Sputtervalve in {area:392}: the next guide passes there"] = "Sputtervalve à {area:392} : le prochain guide y passe",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Guidez {npc:271181} de {npc:267214} hors du ravin jusqu'à la route principale en moins de quatre minutes ; si la canalisation se rompt, redemandez à {npc:267214}.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "La route grimpe vers le nord : c'est {area:1076}. {quest:1483} a une cabane là où la route bifurque vers l'est en direction de {area:461}.",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864} patrouille sur la route à l'est de {area:428}, en direction de {area:430}.",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "Utilisez {npc:212753} à {object:645153} pour un sacrifice consentant et tuez {npc:212753} qui répond. {quest:95883} est élite : il est conseillé de se grouper.",
		["{area:431} is just north up the road."] = "{area:431} est juste au nord sur la route.",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, sur un {npc:1973}",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, sur n'importe quelle harpie Rougefurie",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860} : Héliolites lumineuses ({item:277936}) sur les harpies Rougefurie",
		["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860} : Grish est au {area:1718}, dans le prochain guide",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, à côté de {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, en haut sur la corniche",
		["{npc:12736} at Zoram'gar, at 27"] = "{npc:12736} à Zoram'gar, au niveau 27",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214} : Darthalia à {area:272}",
		["{npc:271181}, on the road"] = "{npc:271181}, sur la route",
		["{npc:4198}, outside the gate"] = "{npc:4198}, devant la porte",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "Ours, rampemousses et lions",
		["Drull's ball and chain"] = "Boulet et chaîne de Drull",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Remplissez l'{item:7768} au {object:107045} à côté de l'auberge",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "Suivez la route vers le sud jusqu'au site de fouilles des nains à {area:359}. {npc:3421} se cache au bord sud des fouilles ; {object:3646} se trouve au fond de l'excavation.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "Depuis {zone:1454} (zeppelin aux tours devant {zone:1458}), prenez un vol pour {area:378}.",
		["Hearth to {area:378} and fly to {area:392}. {quest:874} camps on the shore north of {area:392}."] = "Pierre de foyer vers {area:378}, puis prenez un vol pour {area:392}. {quest:874} campe sur le rivage au nord de {area:392}.",
		["Keep it: the {area:287} coast, later on the route"] = "Gardez-la : la côte de {area:287}, plus loin sur l'itinéraire",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj se cache sur le flanc de colline au-dessus de {area:290}, au sud de Fort-de-Durn, en descendant vers les fleurs.",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "Au sud-ouest de Fort-de-Durn, les {item:3502} poussent sur les collines au-dessus de la rivière.",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "Prenez le zeppelin aux tours devant {zone:1458} pour {zone:1454} et entraînez-vous avant de repartir.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Les fermes à l'est du village de {area:287}. {npc:232} travaille le champ près de la ferme du nord, {npc:2403} celui plus au sud-est ; Ouvriers agricoles et Fermiers d'Hillsbrad sont partout. {npc:2451} s'occupe du champ au sud des fermes.",
		["The smithy"] = "La forge",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "La forge se trouve au centre du village de {area:287}. {npc:2404} et ses apprentis y travaillent ; la {object:1736} est empilée à côté. {npc:2449} arpente la rue au nord.",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "L'hôtel de ville est à l'ouest de {area:287}. {npc:2335} (30) et {npc:2448} sont à l'intérieur avec le Registre municipal d'Hillsbrad ; la Proclamation d'Hillsbrad est affichée à côté. Des Conseillers d'Hillsbrad arpentent le village.",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "{area:288} se trouve au sud du village de {area:287}. Des Mineurs d'Hillsbrad travaillent dans les galeries ; {npc:2305} (30) et {npc:2450} (29) sont tout au fond.",
		["Town hall"] = "Hôtel de ville",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "À l'ouest de Moulin-de-Tarren, des Ours gris, des Rampemousses forestières et des Lions des montagnes affamés parcourent les collines en descendant vers les fermes. Les rampemousses lâchent rarement l'{item:3477} ; il vous en faut un seul.",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} est votre base pour ce guide : la pierre de foyer vous y ramène deux fois. Tout le monde se tient autour de la place du village.",
		["{item:3692}: the Peasants in the fields"] = "{item:3692} : les Paysans d'Hillsbrad dans les champs",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, dans l'Apothicarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, à {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215} : ordres pour {npc:270438}, sur la route de Fort-de-Durn",
		["{npc:2238}'s ball and chain"] = "Boulet et chaîne de {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} est le chien de {npc:232}, à la ferme du nord dans {area:286}.",
		["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388} : le guide précédent vous lie ici, cette étape se coche donc généralement aussitôt",
		["{npc:2391}: Poisons"] = "{npc:2391} : Poisons",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}, près des quais de {area:392}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "La hutte de {npc:5899} se dresse sur la crête au-dessus du point d'eau des hurans, au sud de {area:378}, sur la route de {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899} : l'outre bleue se remplit dans {zone:1440}, au guide suivant",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899} : l'outre rouge de {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, un grand battrodon, nage dans les hauts-fonds au large de {area:391}, à l'est de {npc:3388}.",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Retournez au camp au sud, puis montez à {zone:1456} pour le vol vers {area:378}.",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Retournez au sud-ouest vers {area:421}. Des Elémentaires d’eau souillés dérivent le long de ses rives ; le belvédère se dresse sur l'île et domine l'avant-poste de l'Alliance.",
		["Back west to Zoram'gar before heading east for good."] = "Retournez à Zoram'gar à l'ouest avant de partir pour de bon vers l'est.",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Montez le chemin jusqu'au sommet de {area:2097}. {npc:10646} est retenue captive près de {npc:10896} (29) : éliminez d'abord les gardes et {npc:10896}, puis libérez-la et protégez-la pendant la descente ; des embusqués du Totem sinistre vous attaquent en route.",
		["Felmusk satyrs"] = "Satyres Gangremusc",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Suivez le canyon vers l'est pour quitter les mesas et rejoindre les Salines. Les gobelins et gnomes de {area:2240} sont neutres et donnent des quêtes aux deux factions.",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Suivez la route principale vers l'est après {area:415} (Alliance : restez sur la route). {npc:12678}, un grand grizzly, rôde dans {area:418}, au sud de la route, à l'ouest de {area:421}. Sa patte lance la quête de chasse suivante.",
		["Galak centaurs"] = "Centaures galak",
		["Gazebo"] = "Belvédère",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Échantillons de toxine de la cime du Chagrin ({item:273001}), sur les Cadavres rongés ({npc:264096})",
		["His crate is for Stranglethorn, later on the route"] = "Sa caisse est pour Strangleronce, plus loin sur l'itinéraire",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Continuez vers l'est sur la route. {npc:12858} attend au sud-ouest du Camp de bûcherons chanteguerre. Lui et ses grunts prennent d'assaut {area:2360} : laissez-les attirer l'aggro et restez avec {npc:12858} jusqu'à la mort de {npc:12860}.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Tuez {npc:10720} qui s'en prend à {npc:10638}",
		["Naga brazier"] = "Brasero naga",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Au nord du camp, des araignées envahissent le cimetière de {area:17044}. Utilisez {item:273015} de {npc:264074} sur les Gnawed Corpses ; les Spinners laissent {item:273181}. {npc:264082} se tient au nord : son objet {item:273658} lance {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Au nord-ouest de Bois-brisé, les Satyres Gangremusc campent dans les bois. Chaque satyre peut laisser des cornes.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Descendez par l'ascenseur, puis suivez la route vers l'est à travers les canyons jusqu'à {area:484}, un village tauren au sommet des mesas. Son ascenseur est du côté nord.",
		["Sapphires of Aku'Mai"] = "Saphirs d'Aku'Mai",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "Au sud de Noir-nuage, les harpies de {area:487}. {npc:4490} (31) circule parmi elles : éclaircissez les harpies autour d'elle avant de l'attirer. Les Harpies hurlantes, Volplumes hurlantes et Imploratrices célestes hurlantes de ce lieu sont pour {npc:4877}.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Parlez à {npc:3057}, à {area:1638} : {quest:93739}",
		["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "Descendez de {zone:1456} par un ascenseur. Le camp du Cercle terrestre se trouve au nord des pitons : {npc:264074}, {npc:264072} et {npc:259118}.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Descendez par l'ascenseur. L'œuf repose dans un nid au fond du canyon, à l'un de trois endroits : au sud-est des mesas (52.3,55.2), à l'est (56.4,50.4) ou au sud-ouest (37.6,56.1).",
		["The Earthen Ring"] = "Le Cercle terrestre",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Les furbolgs Vile-sylve tiennent les bois à l'est de {area:421}, au sud de la route. Placez {item:16972} sur {object:178206} et gardez-le : les furbolgs viennent l'abattre. {npc:12918} arrive en dernier ; son totem tombe dans la corbeille.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "Les camps galak remplissent le canyon au nord du Poste de Librevent ; Eclaireurs, Querelleurs et Chasse-vent galak partagent chaque camp. Un {npc:10617} solitaire circule entre les camps : tuez-le dès que vous le croisez, sa note lance une quête pour {area:2237}.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Les Saphirs d'Aku'Mai sont des cristaux bleus sur les parois des tunnels menant au portail de {area:2797}, sous terre et hors de l'instance : plongez depuis la fosse, passez sous le mur et entrez dans la grotte. Les satyres et nagas des tunnels sont élites : il est conseillé de grouper. Les cristaux réapparaissent vite, inutile d'aller loin.",
		["The Wanted poster beside {npc:10537}"] = "L'avis de recherche près de {npc:10537}",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "La fontaine se trouve au milieu de {area:418} : utilisez-y {item:7767}.",
		["The next guide flies on from here to {zone:1454}."] = "Le guide suivant part d'ici en vol vers {zone:1454}.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "On rejoint les saphirs par les ruines englouties au nord de la plage : descendez l'escalier dans la fosse.",
		["Thistlefur Hold"] = "Antre des Crins-de-Chardon",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "À l'ouest du Poste de Librevent, les camps du Totem sinistre sous {area:2097}. Les notes secrètes sont dans les Coffres à documents des camps sud-est, sud-ouest et nord-ouest.",
		["for {npc:5901}, south of {area:392}: next guide"] = "pour {npc:5901}, au sud de {area:392} : guide suivant",
		["{area:2797} ruins"] = "Ruines de {area:2797}",
		["{area:418} fountain"] = "Fontaine de {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, sur les Tisseuses de la cime du Chagrin ({npc:264081})",
		["{item:273658}, from {npc:264082}"] = "{item:273658}, sur {npc:264082}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, près du maître des coursiers du vent",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "La quête suivante de {npc:10428}, Feu sacré, se termine à {zone:1456}, hors de cet itinéraire. Passez-la.",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}, un grand sabre-de-nuit, rôde dans les bois au sud-est du Camp de bûcherons chanteguerre. Sa griffe lance la quête de chasse suivante.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, une panthère des ombres, rôde dans les bois autour de {area:426}, à l'ouest du camp Gangremusc. Sa tête lance la quête de chasse suivante.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717} remonte la plage vers le nord jusqu'à un brasero naga. Éteignez le brasero, puis protégez-le pendant les vagues de nagas jusqu'à la mort de Vorsha la Flagellante.",
		["{npc:12717}: starts his escort at once"] = "{npc:12717} : son escorte commence aussitôt",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718} : seulement si vous portez les pages du manuel",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} Sancrea propose ensuite une quête à {area:2797} ; laissez-la sauf si vous avez un groupe.",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}, un élémentaire d'eau corrompu, dérive dans {area:421}. Son objet {item:16408} lance une quête pour Bois-brisé.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, un ajout de Forever, se tient sur la rive ouest de {area:421} avec trois quêtes rapides de tueur de dragon.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} se tient au sommet d'une mesa à l'est des camps galak. Pour {quest:1149}, avancez jusqu'au bout des planches à côté de lui et sautez : vous atterrissez sans dommage.",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454} : sa lettre est pour Martek l'Exilé dans {zone:1418}, vers le niveau 38",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}, un élémentaire de roche qui frappe fort, arpente les falaises de {area:482}. {npc:4499} est élite : il est conseillé de grouper.",
		["{object:176344}, north-west camp"] = "{object:176344}, camp nord-ouest",
		["{object:176344}, south-east camp"] = "{object:176344}, camp sud-est",
		["{object:176344}, south-west camp"] = "{object:176344}, camp sud-ouest",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868} jonche les Salines au nord de la piste. Scorpides ravageurs et Tortues nacrétoile parcourent la moitié nord, des Charognards des Salines tournoient au-dessus, et des Basilics du sel gemme paissent à l'ouest de la piste. Les Peaux de cristal du sel gemme parcourent le centre des Salines et les Contemplateurs du sel gemme (34-35, cinq niveaux au-dessus de vous : un à la fois) l'extrême sud.",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back to {area:272}"] = "Retour à {area:272}",
		["Clam beds"] = "Bancs de praires",
		["Daggerspine naga"] = "Nagas Daguéchine",
		["Daggerspine shore"] = "Rivage des Daguéchine",
		["Fly to {area:1637}"] = "Prenez un vol pour {area:1637}",
		["Fly to {area:1638} from Shadowprey and train with {npc:3033} on {area:1639}, then fly on to {zone:1454}."] = "Depuis Proie-de-l'Ombre, prenez un vol pour {area:1638} et entraînez-vous auprès de {npc:3033} sur {area:1639}, puis prenez un vol pour {zone:1454}.",
		["Fly to {area:460}"] = "Prenez un vol pour {area:460}",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "Prenez un vol pour {area:484}. {npc:5905} se cache dans une petite grotte, dans la paroi du canyon au nord-est du poste.",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "Suivez la route au nord de {area:272} jusqu'aux contreforts d'Alterac. {quest:535} attend près du camp du Syndicat ; donnez-lui la bière.",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "Suivez le rivage vers l'ouest au-delà de la baie d'{area:271} ; les murlocs Aileron déchiré campent sur les plages plus loin.",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "Continuez au nord jusqu'à {area:598}. Les Oracles se tiennent parmi les autres nagas à son extrémité nord ; attirez-les un par un.",
		["Kolkar ears"] = "Oreilles de Kolkar",
		["Shadowstalker scalp"] = "Scalp de traqueur des ténèbres",
		["Shindigger keg"] = "Tonneau de Shindigger",
		["Slitherblade Oracles"] = "Oracles Ondulame",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "Au sud-ouest, les Yétis des grottes et les Yétis féroces (30-31) peuplent les grottes des collines à l'ouest de {area:272} ; environ un sur seize porte le bâton.",
		["Syndicate missives"] = "Missives du Syndicat",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "La tâche suivante de Thaivand se termine au cimetière d'{area:271} et le magus propose une mission de donjon : laissez les deux.",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "Les Traqueurs des ténèbres Fielfurie de {area:603} restent invisibles jusqu'à leur attaque ; environ un sur trois porte un scalp.",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "Les Détrousseurs et Larrons du Syndicat (32-33) autour des camps à l'ouest de la route portent les missives ; environ un sur trois en laisse tomber une.",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "Le tonneau se trouve avec quelques autres au camp du Syndicat, sur la côte sud-est de {area:287}.",
		["The {area:279} traitors"] = "Les traîtres de {area:279}",
		["Torn Fin beach"] = "Plage des Aileron déchiré",
		["Torn Fin murlocs"] = "Murlocs Aileron déchiré",
		["Train"] = "Entraînement",
		["Train your new spells."] = "Apprenez vos nouveaux sorts.",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "Utilisez le {item:13892} de {npc:11596} sur un Vieux kodo, un Kodo mourant ou un {npc:4702} du cimetière, puis ramenez le kodo apprivoisé à {npc:11596}. Cinq kodos, un à la fois.",
		["for {npc:5901}: from Stranglethorn, next guide"] = "pour {npc:5901} : depuis Strangleronce, guide suivant",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388} : hôtel des ventes ou un alchimiste, pour {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, pour {npc:2333}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863} attend dans la tour en ruine de {area:2405}, dans les terres au sud-est.",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877} : pour {npc:715} à Strangleronce",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229} : pour {zone:1413}, plus loin sur l'itinéraire",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770} : pour {area:321} en Arathi, plus loin sur l'itinéraire",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, si vous l'avez",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} se tient dans le poste ; {npc:5641} et {npc:4498} attendent sur la butte à l'ouest, au-dessus de {area:596}.",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639} attend dans la Herse ; {npc:5640} se tient dans {object:172961} à l'ouest de la ville. Célestes : {npc:4949} attend dans le fort Grommash, dans {object:172957}.",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "La mission suivante de {npc:5641} vous envoie contre un seigneur démon escorté d'élites : passez-la.",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "La quête suivante de {npc:5641}, {quest:1431}, vous renvoie à {zone:1454} pour rien : laissez-la.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} se tient dans {object:172957}.",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} lance aussi Elemental Aid ({area:1717}), la suite 33-40 menant à The Tempest's Weapons : forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905} : votre {item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515} demande un {item:3388}, un objet d'{skill:171} : achetez-en un à l'hôtel des ventes ici si vous pouvez (ou demandez à un alchimiste). Sans potion, passez les étapes de l'élixir à {area:287}.",
		["{zone:1454} class quests"] = "Quêtes de classe à {zone:1454}",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Retournez au camp, au nord.",
		["Back to {object:3202}."] = "Retour à {object:3202}.",
		["Elder tigers and Lashtail raptors"] = "Anciens tigres et raptors flagellants",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Suivez la route vers le nord depuis {object:3202} ; le camp de chasse de Nesingwary se trouve sur la colline au nord-est de la rivière. Dès maintenant, gardez chaque page de {quest:338} ramassée : {npc:716} les demandera plus tard.",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "Suivez la route vers le sud jusqu'à {area:35}, à la pointe sud de la vallée, et entrez par le tunnel dans les falaises. Restez sur la route : la jungle alentour est bien au-dessus de votre niveau. {npc:2858}, le maître de vol de la Horde, attend sur le ponton supérieur.",
		["Follow the road south to {object:3202}."] = "Suivez la route vers le sud jusqu'à {object:3202}.",
		["Green Hills pages"] = "Pages des Vertes collines",
		["Hearth to {area:35}"] = "Pierre de foyer vers {area:35}",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Au nord-ouest de Grom'gol, {area:104} s'étend sous l'eau au large de la côte. L'{item:4094} repose au fond de la mer près des ruines englouties ; surveillez votre souffle et les murlocs.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Les pages de {item:2755} tombent à environ 1 % chacune sur les trolls Bloodscalp et Skullsplitter ; gardez chaque page ramassée et cherchez le reste à l'hôtel des ventes. {npc:716} prend les chapitres plus loin dans ce guide.",
		["Shadowmaw panthers"] = "Panthères Ombregueule",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Les Tigres de Strangleronce et les Panthères (32-33) parcourent les collines à l'est du camp, le long du lac.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Les Raptors flagellants (35-36) chassent dans la jungle juste au nord-est de {object:3202}.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Les Panthères Ombregueule (37-38) rôdent dans la jungle à l'est des collines Mosh'Ogg et au nord-est vers le lac ; elles attaquent en camouflage. Ramassez chaque page des Vertes collines trouvée en chemin.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Les Panthères Ombregueule viendront bien plus tard, près de {object:3202}",
		["The camp by the river"] = "Le camp près de la rivière",
		["The zeppelin lands at the tower on the west side of the camp."] = "Le zeppelin arrive à la tour à l'ouest du campement.",
		["Venture Co. camp"] = "Camp de la KapitalRisk",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497} : pour les Hautes-terres Arathies, plus loin sur l'itinéraire",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901} : {npc:3527} et votre {item:5177}",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Le camp des chasseurs disparus de {npc:773} est celui de Nesingwary : marchez parmi ses tentes et l'enquête est terminée. Des Crocilisques des rivières se trouvent le long de la rivière sous le camp.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Retour à {area:321}",
		["Boulderfist camp"] = "Camp Rochepoing",
		["Fleshstalker raptors"] = "Raptors charognards",
		["Fly to {area:272}"] = "Volez jusqu'à {area:272}",
		["Fly to {object:3202}"] = "Volez jusqu'à {object:3202}",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Des Charognards des hautes-terres ({npc:2561}) (36-37) chassent dans le sud des hautes-terres, une meute au nord de {area:316} et une autre dans la plaine à son ouest. Attirez-les un par un.",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "Des Arpenteurs des hautes-terres ({npc:2559}) parcourent les collines tout autour de {area:321} ; eux et les Vandales des hautes-terres plus à l'ouest lâchent les yeux.",
		["Highland raptors"] = "Raptors des hautes-terres",
		["Into the {zone:1418}"] = "Vers {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Continuez vers le nord sur la route ; le coffre se trouve sur le site de fouilles d'{area:1517}, au pied des ruines au nord-ouest de la route.",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "Les Brutes Rochepoing ({npc:2566}) campent devant la salle des ogres au sud de {area:321} ; les Magus se tiennent parmi elles. Attirez-les un par un.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Le cercle intérieur se trouve au sud du cercle ouest, à l'est de Stromgarde.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "La forteresse orque au bout est de la route. {npc:2851}, la maîtresse des coursiers du vent, se tient près de la porte.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Les petits élémentaires dérivent dans la plaine juste à l'ouest du camp de {npc:2921}. Tout élémentaire de roche de la zone peut lâcher les Fragments d'élémentaire de roche ({item:7848}) de {npc:6868} : gardez-les.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "La tâche suivante de la pierre demande Fozruk, un élite de niveau 42 : laissez-la.",
		["The violet shards glow just off the road a short way west of {area:321}."] = "Les éclats violets brillent juste à côté de la route, un peu à l'ouest de {area:321}.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} se trouvent tout au fond de la gorge.",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "Theldurin l’Egaré se trouve parmi les ruines naines de {area:345}, au sud de la {area:1877}.",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "À l'ouest de la crique, les Ecumeurs ({npc:2595}) et Sorcières Daguéchine (38-40) tiennent le rivage : attirez-les un par un. Les deux épaves gisent dans les hauts-fonds au large, les cartes et journaux à l'intérieur ; les gemmes reposent au fond de la mer autour des épaves.",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "Votre maître est à {area:1638}, à un vol d'{zone:1454} : {npc:3033} (druides) sur la {area:1639}, {npc:246344} (paladins). De là, volez jusqu'à {area:380}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["for Helgrum in {area:75}, around level 42"] = "pour Helgrum l'Agile à {area:75}, vers le niveau 42",
		["for {npc:2487} in {area:35}, around level 44"] = "pour {npc:2487} à {area:35}, vers le niveau 44",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge."] = "{area:340} est la forteresse de la Horde bâtie dans les falaises, à l'extrémité ouest de la zone.",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "La suite {quest:678} de {npc:2771} vise des élites Rochepoing : laissez-la.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920} : seulement si vous avez {item:2868} ({skill:164} ou l'hôtel des ventes)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} n'a pas de maître des chasseurs ni des chamans : prenez plutôt le zeppelin d'{zone:1454} à la même tour et entraînez-vous en ville, puis prenez le zeppelin de {zone:1458} à la tour devant la porte principale d'{zone:1454}.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106} : la lettre de Fizzle, de {area:439}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
