		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Plus à l'est sur la route, {npc:11077} garde le chaudron des {area:200}.",
		["Flayers and Rock Stalkers"] = "Écorcheurs et Traqueuses des rochers",
