		["Mark {npc:10904} with the {item:12815}"] = "Marquez {npc:10904} avec {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marquez {npc:10905} avec {item:12815}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "Au nord, jusqu'au camp de bûcherons ; posez le tonneau de termites au milieu de la scierie.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Allez vers l'est jusqu'à la cabane de {npc:1855}, au bord de {area:2619}, et écoutez-le.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Allez vers le nord-est jusqu'au cimetière ({area:3077}) ; vous quittez {zone:1451} par le col tout proche.",
		["Ride north-east to {area:3447}."] = "Allez vers le nord-est jusqu'à {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Allez vers le nord-ouest jusqu'à la cabane de {npc:1855}.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Allez vers le sud jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine à l'ouest de la ville. Placez-vous sur le seuil de chacune des quatre tours avec {item:12815} pour la marquer ; restez en bordure de la ville. Utilisez {item:12627} près des silos au centre de la ville pour faire apparaître des Parasites temporels.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Allez vers le sud-est jusqu'à {area:3447}, au pied des falaises d'Un'Goro.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Allez vers le sud-ouest jusqu'aux ruines du {area:2738}. Le {object:179565} pour {npc:11801} se trouve dans l'une des maisons en ruine.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Allez vers le sud-ouest jusqu'à {npc:10667}, à Andorhal.",
		["Ride west to the Horde camp north of {area:2744}."] = "Allez vers l'ouest jusqu'au camp de la Horde au nord de la {area:2744}.",
		["Ride west to the walled hold in the middle of the desert."] = "Allez vers l'ouest jusqu'au fort fortifié au milieu du désert.",
		["Scourge Champions"] = "Champions du Fléau",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Les Champions du Fléau parcourent {area:2270}, au nord de la chapelle. Passez {item:13156} de {npc:11063} sur chacun de ceux que vous tuez : les crânes qui résonnent sont ceux qu'il veut.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Des Geysers de silithyste jaillissent dans le désert du sud. Marchez dans le silithyste qu'ils laissent et portez-le à l'extracteur de silithyste de la Horde, au camp de Kirika ; combattre ou monter en selle vous le fait lâcher.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Les Ecorcheurs Cinglepierre et les Traqueuses des rochers parcourent les dunes au sud-ouest du camp de Kirika.",
		["The libram lies further north, on the way to {area:190}."] = "Le libram se trouve plus au nord, sur la route de {area:190}.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Le col venant d'Un'Goro débouche sur {area:3077}, le cimetière du nord-est de {zone:1451}. {npc:13220} se tient parmi les tombes.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "La sacoche se trouve dans les montagnes de l'extrême sud, au-delà du Campement de Bronzebeard. Poigne-de-mort, un scorpide élite, patrouille à proximité : prenez-la pendant qu'il s'éloigne.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Le bouclier se trouve à {area:201}, au sud de la cabane de {npc:1855}.",
		["The spare texts from the cultists"] = "Les textes en trop des cultistes",
		["Twilight Vanguard"] = "Avant-garde du Crépuscule",
		["Use {npc:10980} on {npc:10977}"] = "Utilisez {npc:10980} sur {npc:10977}",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "Vers l'ouest jusqu'à la {area:152}. Le prochain guide commence à {zone:1458}, un peu plus à l'ouest.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "La bataille de Comté-de-Darrow, quête de {npc:10667}, se termine contre des élites. Passez-la.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803} arpente le camp de l'Avant-garde, à l'extrême sud-ouest. Chaque cultiste ici laisse tomber des Textes du crépuscule cryptés, quête ou non : récupérez-en vingt, dix pour {npc:15306} et dix pour Ortell.",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804} se tient dans l'avant-poste à l'ouest du {area:3425}. Complétez vos Textes du crépuscule cryptés jusqu'à vingt sur les cultistes du coin.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} tient le camp de l'ouest.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, du côté ouest du fort",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back south to the Sanctuary, a short ride."] = "Retournez au sud au Sanctuaire d'émeraude, un court trajet.",
		["Dungeon instead of grinding"] = "Donjon au lieu de tuer des monstres",
		["Grind to 60"] = "Monter au niveau 60",
		["In {zone:1454}: fly from {area:2255}"] = "Pour {zone:1454} : volez depuis {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "Pour {zone:1456} : volez depuis {area:2255}",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Seulement avec 30 {quest:6031}, et seulement si vous êtes Neutre avec les Grumegueules : suivez la route vers le nord jusqu'au {area:1769} ; {npc:11557} commerce juste après l'entrée.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Facultatif. Faire {area:2279}, {area:2057}, le bas du Pic Rochenoire ou {area:1584} en groupe au lieu de tuer des monstres vous y amène plus vite.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Facultatif : en groupe, un donjon 55-60 remplace l'enchaînement de monstres ci-dessous.",
		["Ride east along the road to {area:2255}."] = "Suivez la route vers l'est jusqu'à {area:2255}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Suivez la route vers le nord, après {area:1763}, jusqu'au {area:1997}.",
		["South to the Sanctuary once more."] = "Retournez encore au sud au Sanctuaire d'émeraude.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Le Fragment de la Gangrevigne de {npc:11801} demande {area:2577}. Passez-la.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} vous envoie ensuite contre {npc:10738}, un élite dans sa grotte. Passez-la.",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Les Scorpides blindés rampent dans les plaines à l'ouest de {area:362}. Apprivoisez-en un, puis retournez voir {npc:3171}.",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Retournez à l'est jusqu'au rivage au nord de {npc:275657}. Les Eclaireurs et les Domestiques fouette-bile tiennent la plage sous {area:370}. Chasseurs : apprivoisez un {npc:3107} sur la plage.",
		["Back south to {area:362}."] = "Retournez au sud jusqu'à {area:362}.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to {area:362}."] = "Retournez à {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Retournez voir {npc:5875} dans {object:172960}. Utilisez les {item:7464} sur le cercle d'invocation et vainquez le marcheur du Vide pour le lier.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Suivez la route au nord depuis {area:362} jusqu'à la porte principale d'{zone:1454}, juste à l'ouest de {area:817}. {npc:3352} se tient avec les maîtres des chasseurs dans {object:172958}.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Dirigez-vous vers le sud à travers les îles. Les idoles des loas sont éparpillées sur les îles du sud ; les Trolls vaudous et les Trolls maléficiés les gardent et laissent tomber les Pendentifs maléficiés. {quest:826} et la cage de Minshina se trouvent sur l'île la plus au sud.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["Prickly pears"] = "Figues de Barbarie",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Eclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}. {npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Les figues de Barbarie poussent parmi les huttes des huran juste à l'ouest de la ville.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, de l'autre côté du pont ; chacun d'eux peut laisser tomber une {item:6486}.",
		["Thunder lizards across the river"] = "Lézards-tonnerre de l'autre côté du fleuve",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} se trouve à l'ouest de Sen'jin. Les trois plans d'attaque sont posés au sol parmi les tentes des centaures. {npc:275811} est aussi retenue à la Combe.",
		["{area:817}'s mouth"] = "Entrée de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, à votre point de départ",
		["{npc:265809}'s campfire"] = "Feu de camp de {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881} : enchanteurs uniquement, le résidu s'obtient en désenchantant des Pendentifs maléficiés",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} se tient sur le rivage à l'est de {area:362}. Le trident, la bannière et la dague traînent sur la plage autour de lui.",
		["{npc:3102} hooves"] = "Sabots de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de retour à {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142} : {npc:275666}, un géant des mers élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} se tient juste à l'entrée de la grotte ; {npc:3159} au fond de la grotte, derrière lui.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} attend dans l'Antre, le bâtiment juste à l'ouest de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, dans la tour de guet",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, le maître des guerriers à côté de l'Antre",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, le maître des chasseurs à côté de l'Antre",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, le maître des voleurs dans l'Antre",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, le maître des démonistes au fond de la grotte",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, le maître des chamans à côté de l'Antre",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} gît blessé au pied des collines au nord-ouest de l'Antre.",
		["{npc:3294}, by the inn"] = "{npc:3294}, près de l'auberge",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, le maître des mages, à l'entrée de l'Antre",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} se tient devant l'Antre. {area:639} est la colline juste au sud : buvez-y le {item:6635} pour voir la {npc:5891}, puis rapportez le {item:6656} à {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, sur {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La porte principale d'{zone:1454} se trouve juste à l'ouest de {area:817}. {npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}.",
} end)()
t.guides["forever/horde/orc/02-the-barrens"] = (function() return {
		["Follow the road south-east to {area:392} on the coast."] = "Suivez la route au sud-est jusqu'à {area:392}, sur la côte.",
		["Razormane camp"] = "Camp Tranchecrin",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} campe au bord de la route à l'est, vers {area:392}.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {npc:2523}, votre {item:5176} et le {item:263412}",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders et les gardes tombés sont juste au sud-ouest de la tour. Prenez la Plume porte-bonheur de Raani et la chevalière Shadowsong sur les corps.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De retour à {quest:92529} : des Mande-foudre al'aketh et {npc:251662} emplissent le village, les Caches de fournitures ({object:576179}) se trouvent entre les maisons et {npc:251966} attend à son extrémité sud-est.",
		["Back to {area:16635}"] = "Retour à {area:16635}",
		["Back to {area:16638}"] = "Retour à {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Retournez voir {npc:268592}. Attendez qu'il allume {npc:268762}, puis portez la flamme directement jusqu'à {npc:268679}, à côté de {npc:252382} à {area:16638}, avant la fin du temps imparti.",
		["Find {npc:258130}"] = "Trouvez {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "Suivez la route vers le sud jusqu'à {area:16624}, au milieu de l'île.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Allez vers le nord dans la {area:16631} ; {npc:257944} campe à sa lisière sud.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Allez au sud-ouest jusqu'à la {area:17674}. {npc:252155} est au sommet ; {item:254871} se trouve à côté de lui.",
		["Heal the injured druids in the Nightfang Den"] = "Soignez les druides blessés dans la tanière des Crocs-de-la-nuit",
		["Leaving {area:16635}"] = "Départ de {area:16635}",
		["Listen to {npc:252448}'s story"] = "Écoutez l'histoire de {npc:252448}",
		["Listen to {npc:256083}"] = "Écoutez {npc:256083}",
		["Northern {zone:1412}"] = "Nord de {zone:1412}",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Des Mouches-cirrus agaçantes et des {npc:250873} parcourent le bosquet juste au sud-est du village.",
		["Raw Windstones"] = "Pierres de vent brutes ({object:613286})",
		["Skyhoppers"] = "Sauteciels",
		["Skyhoppers hop about the fields just west of Valennia."] = "Des Sauteciels ({npc:251727}) sautillent dans les champs juste à l'ouest de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Des Pommes d’orage mûres et de la Poussière de voltemouche jonchent le verger ; des Bandits affamés ({npc:252802}) le pillent. Des trotteurs des trombes paissent dans les champs à l'est. L'assemblage brisé flotte à la lisière nord du verger.",
		["Talk to {npc:251902}"] = "Parlez à {npc:251902}",
		["Talk to {npc:251968}"] = "Parlez à {npc:251968}",
		["Talk to {npc:252383}"] = "Parlez à {npc:252383}",
		["Talk to {npc:252800}"] = "Parlez à {npc:252800}",
		["Talk to {npc:253576}"] = "Parlez à {npc:253576}",
		["Talk to {npc:254089}"] = "Parlez à {npc:254089}",
		["Tell {npc:252800} you're ready"] = "Dites à {npc:252800} que vous êtes prêt",
		["The Al'Aketh camp"] = "Le camp al'aketh",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Les Pierres de vent brutes ({object:613286}) sont des cristaux bleus sur les pentes autour du village.",
		["The orchard"] = "Le verger",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La reine plane à l'extrémité sud-est du bosquet, sur le chemin du retour depuis les pierres.",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Les affaires des réfugiés sont éparpillées le long de la rive nord du {area:16625} ; {npc:259013} est à son extrémité nord-ouest.",
		["The standing stones"] = "Les pierres dressées",
		["The turncoat"] = "Le traître",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "La maison du traître se trouve dans les {area:16626}, au nord-ouest de {area:16638}. {npc:273017} attend tout près ; ses assassins rôdent autour de la maison.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "Le {area:16629} est au nord de {area:16638}. Frayez-vous un chemin à travers les gardes jusqu'à {npc:253576}, du côté est.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Vous quittez l'île pour de bon. {npc:259119} attend là où se pose le dirigeable.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Vous vous réveillez à {area:16635}, au nord de l'île. {npc:251362} se tient près du chemin, {npc:251361} au centre du village.",
		["search the dead cultist in the house"] = "fouillez le cultiste mort dans la maison",
		["search the wardrobe"] = "fouillez l'armoire",
		["talk to {npc:251684}"] = "parlez à {npc:251684}",
		["talk to {npc:251902}"] = "parlez à {npc:251902}",
		["talk to {npc:251968}"] = "parlez à {npc:251968}",
		["talk to {npc:252155}"] = "parlez à {npc:252155}",
		["talk to {npc:252476}"] = "parlez à {npc:252476}",
		["talk to {npc:257554}"] = "parlez à {npc:257554}",
		["the bounty board"] = "le tableau des primes",
		["{area:16624} turn-ins"] = "Quêtes à rendre à {area:16624}",
		["{area:16635} turn-ins"] = "Quêtes à rendre à {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "Le {area:16663} est à l'ouest de {area:16638}, sur la route côtière.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} pousse autour du camp d'{npc:257944} et des criailleuses le survolent. Le camp al'aketh à l'est d'elle contient {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{npc:251361}'s errands"] = "Les commissions de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361} : un mot de votre maître",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361} : examinez {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361} : lisez {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361} : {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, le maître des druides, au rez-de-chaussée de l'arbre derrière {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374} : {npc:5873} et votre {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, dans la tour de guet",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, dans la tour de guet",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382} : {npc:2523}, votre {item:5176} et {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} et {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} et {npc:258134} sont dans le camp du culte à l'est d'{npc:257944}. {npc:254151} se tient à sa lisière. Haalien lâche aussi {quest:94490} : lisez-la pour commencer la quête suivante. Pour {quest:94489}, entrez dans la tanière des Crocs-de-la-nuit, soignez 7 druides blessés et trouvez {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} rôde au sud du village, parmi les Fièregriffes. {npc:254589} est un élite : mieux vaut être en groupe.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} se tient dans les {area:16626}, juste au nord-ouest de la ville.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} attend sur la route au nord de {area:16638}, en direction du {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} tient {item:263993} du côté ouest du sanctuaire.",
		["{npc:257944} again"] = "De nouveau {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, une dernière fois",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, près de l'aire d'atterrissage : pour {npc:3033} à {zone:1456}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119} : gardez-la, Thrall à {zone:1454} vient deux guides plus tard",
		["{npc:263664}'s campfire"] = "Le feu de camp de {npc:263664}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} se trouve au sud de Shen’dar. {npc:257065} vous attend à son entrée ; fouillez l'armoire de la maison derrière lui.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Retournez à l'est jusqu'à {area:358} : les Chamans Dos-hirsute s'y tiennent parmi les huran.",
		["Back south-east to the {area:396}."] = "Retournez au sud-est jusqu'au {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Retournez voir {npc:5888} au camp. La {npc:5891} attend sur la mesa à l'est du camp : buvez-y le {item:6635} pour la voir, puis rapportez le {item:6656} à la prophétesse.",
		["Back west to the camp."] = "Retournez à l'ouest jusqu'au camp.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Les Sangliers de guerre paissent au nord du sanctuaire ; les huran Dos-hirsute tiennent le ravin au nord-est. {npc:8554} se tient à son extrémité est, et la {object:3076} gît par terre dans le camp.",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Traversez vers le nord-ouest au-delà de {zone:1456} jusqu'au {area:398}, à l'extrême nord de {zone:1412}.",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "Suivez le chemin vers le sud hors du camp jusqu'à la tente du prophète, au pied des collines.",
		["Galak centaurs"] = "Centaures galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Allez au nord jusqu'à {area:225}, à l'est de {zone:1456}. {npc:3233} se tient au pied des rochers ; les Intrus Dos-hirsute creusent dans le cimetière et l'{npc:2994} attend au sommet.",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Les Loups Alpha des prairies rôdent parmi les loups dans les plaines autour de {npc:275789} et du camp galak à l'est.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Les Loups des prairies et les Trotteurs des plaines adultes parcourent les plaines autour du village.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Prenez un ascenseur jusqu'aux mesas. {npc:2995} s'occupe des coursiers du vent sur le piton central ; {npc:3057} se tient dans la grande tente.",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Swoops glide over the plains all around Bloodhoof."] = "Les Rapaces planent au-dessus des plaines tout autour de Sabot-de-Sang.",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "Les centaures galak campent dans les plaines à l'est du puits ; {npc:275767} les mène.",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Les gnolls crin-pâle tiennent {area:818}, au sud du site de fouilles et à l'ouest de Sabot-de-Sang. {npc:272203} est retenu dans leur camp : escortez-le dehors.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Les harpies Furie-des-vents tiennent {area:819}, au nord et à l'ouest du puits.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Les nains du {area:404} portent les Piolets de prospecteur. Brisez-les à la forge des nains, sur le site de fouilles.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Les gobelins exploitent la mine dans les collines au nord-est du puits. {quest:765} se tient au fond de la mine ; ses {item:281031} lancent {quest:98424}, et les autres pages se trouvent dans la mine.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "L'encens se consume en dix minutes : courez tout droit vers l'est le long des collines du sud jusqu'au {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Le sanctuaire d'An'she et Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "La pierre se dresse dans le col qui sort de {zone:1412}, sur votre route vers l'est. Utilisez-y la {item:15710} et vainquez Lunegriffe.",
		["The well lies south-east of the village."] = "Le puits se trouve au sud-est du village.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "La caravane détruite se trouve au nord-ouest des centaures, à l'est de la route de {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Vous commencez sur la mesa de {area:221}. {npc:2980} et le chef se tiennent près de la grande tente au centre.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, à la forge du site de fouilles",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203} : les Rôdeurs des basses plaines parcourent les plaines autour de {area:225}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789} se tient dans {area:821}, un peu à l'est du puits.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} se tient au bord nord du village. Kyle veut de la {item:287505} prise sur les trotteurs des plaines.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, à l'extrémité nord du village",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, pour Hamuul à {zone:1456}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} se tient au bord du {area:404}, au sud du puits.",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988} campe près du {area:396}, au sud-est de Sabot-de-Sang.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} est assise près de la tente au bord est du camp ; {object:2907} est posée à côté d'elle.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, pour {npc:3057} à {zone:1456}",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, le maître des druides à côté de lui",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, la maîtresse des chasseurs",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, la maîtresse des chamans au camp",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Quête de {npc:3063} : battez trois Guerriers novices (ou des joueurs en duel) à côté de lui.",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441} : pour {quest:860} à {area:380}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769} : pour {npc:3448} à {area:380}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} se tient au {area:221}. {quest:1516} requiert le niveau 4, que vous atteignez avec les quêtes rendues ici.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888} : {npc:5873} et votre {item:5175}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775} se tient à l'extrémité ouest du camp, à l'angle nord-ouest des collines où rôdent les Pumas des montagnes : prenez sa quête, chassez les pumas de là vers le sud et l'est, puis remontez voir {npc:2980}.",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, un loup solitaire, rôde dans les plaines à l'ouest du village. Les Traqueurs des prairies et les Pumas des basses plaines parcourent les plaines au nord et à l'ouest du village.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Retournez à l'est jusqu'au rivage au nord de {npc:275657}. Les Eclaireurs et les Domestiques fouette-bile tiennent la plage sous {area:370}. Chasseurs : apprivoisez un {npc:3107} sur la plage.",
		["Back south to {area:362}."] = "Retournez au sud jusqu'à {area:362}.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to {area:362}."] = "Retournez à {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Retournez voir {npc:5875} dans {object:172960}. Utilisez les {item:7464} sur le cercle d'invocation et vainquez le marcheur du Vide pour le lier.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Suivez la route vers l'est hors de la vallée jusqu'au {area:367}, sur la côte.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["Prickly pears"] = "Figues de Barbarie",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Eclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}. {npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Les figues de Barbarie poussent parmi les huttes des huran juste à l'ouest de la ville.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, de l'autre côté du pont ; chacun d'eux peut laisser tomber une {item:6486}.",
		["Thunder lizards across the river"] = "Lézards-tonnerre de l'autre côté du fleuve",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Traversez à gué jusqu'à l'île de l'Écho la plus au nord. La Matriarche y rôde parmi les raptors.",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
